{"command":"cd /workspace && cat > build.rs <<'EOF'
//! Build script: converts `data/ascii_table.txt` (human readable
//! transliteration table) into compact binary tables that are embedded
//! into the executable with `include_bytes!`.
//!
//! Generated files (in `OUT_DIR`):
//!   * `ascii_cps.bin`  - sorted u32 (LE) code points having a non-empty output
//!   * `ascii_offs.bin` - u32 (LE) offsets into `ascii_strs.bin`, one more than
//!                        the number of code points (end offset)
//!   * `ascii_strs.bin` - concatenated ASCII outputs

use std::env;
use std::fs;
use std::path::Path;

fn main() {
    let manifest_dir = env::var("CARGO_MANIFEST_DIR").unwrap();
    let out_dir = env::var("OUT_DIR").unwrap();
    let table_path = Path::new(&manifest_dir).join("data").join("ascii_table.txt");
    println!("cargo:rerun-if-changed={}", table_path.display());
    println!("cargo:rerun-if-changed=build.rs");

    let content = fs::read_to_string(&table_path).expect("cannot read data/ascii_table.txt");

    let mut cps: Vec<u8> = Vec::new();
    let mut offs: Vec<u8> = Vec::new();
    let mut strs: Vec<u8> = Vec::new();
    let mut last_cp: Option<u32> = None;

    for (lineno, line) in content.lines().enumerate() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (hex, out) = match line.split_once('\t') {
            Some(pair) => pair,
            None => panic!("malformed table line {}: {:?}", lineno + 1, line),
        };
        let cp = u32::from_str_radix(hex, 16)
            .unwrap_or_else(|_| panic!("bad code point on line {}", lineno + 1));
        if let Some(prev) = last_cp {
            assert!(cp > prev, "table must be sorted by code point (line {})", lineno + 1);
        }
        last_cp = Some(cp);
        assert!(out.is_ascii(), "non ascii output on line {}", lineno + 1);
        cps.extend_from_slice(&cp.to_le_bytes());
        offs.extend_from_slice(&(strs.len() as u32).to_le_bytes());
        strs.extend_from_slice(out.as_bytes());
    }
    offs.extend_from_slice(&(strs.len() as u32).to_le_bytes());

    fs::write(Path::new(&out_dir).join("ascii_cps.bin"), cps).unwrap();
    fs::write(Path::new(&out_dir).join("ascii_offs.bin"), offs).unwrap();
    fs::write(Path::new(&out_dir).join("ascii_strs.bin"), strs).unwrap();
}
EOF
echo done"}

