{"command":"cd /workspace && cat > src/ascii.rs <<'EOF'
//! Unicode to ASCII transliteration.
//!
//! The mapping is a per-code-point table embedded at build time (see
//! `build.rs` and `data/ascii_table.txt`). ASCII characters are kept as they
//! are, code points without an entry in the table are dropped.

static CODE_POINTS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/ascii_cps.bin"));
static OFFSETS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/ascii_offs.bin"));
static STRINGS: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/ascii_strs.bin"));

#[inline]
fn read_u32(table: &[u8], index: usize) -> u32 {
    let start = index * 4;
    u32::from_le_bytes([
        table[start],
        table[start + 1],
        table[start + 2],
        table[start + 3],
    ])
}

/// Number of entries in the table.
fn table_len() -> usize {
    CODE_POINTS.len() / 4
}

/// Return the ASCII representation of a single character.
pub fn char_to_ascii(c: char) -> &'static str {
    if c.is_ascii() {
        let cp = c as usize;
        // Safe: ASCII_CHARS only contains ASCII bytes.
        return &ASCII_CHARS[cp..cp + 1];
    }

    let needle = c as u32;
    let mut low = 0usize;
    let mut high = table_len();
    while low < high {
        let mid = low + (high - low) / 2;
        let value = read_u32(CODE_POINTS, mid);
        if value == needle {
            let start = read_u32(OFFSETS, mid) as usize;
            let end = read_u32(OFFSETS, mid + 1) as usize;
            // The build script guarantees these bytes are ASCII.
            return std::str::from_utf8(&STRINGS[start..end]).unwrap_or("");
        } else if value < needle {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    ""
}

/// Convert a whole string to its ASCII representation.
pub fn to_ascii(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    for c in input.chars() {
        output.push_str(char_to_ascii(c));
    }
    output
}

/// ASCII table used to return single-character slices without allocating.
static ASCII_CHARS: &str = "\
\u{00}\u{01}\u{02}\u{03}\u{04}\u{05}\u{06}\u{07}\u{08}\u{09}\u{0a}\u{0b}\u{0c}\u{0d}\u{0e}\u{0f}\
\u{10}\u{11}\u{12}\u{13}\u{14}\u{15}\u{16}\u{17}\u{18}\u{19}\u{1a}\u{1b}\u{1c}\u{1d}\u{1e}\u{1f}\
 !\"#$%&'()*+,-./0123456789:;<=>?\
@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_\
`abcdefghijklmnopqrstuvwxyz{|}~\u{7f}";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ascii_passthrough() {
        assert_eq!(to_ascii("hello world"), "hello world");
        assert_eq!(char_to_ascii('a'), "a");
        assert_eq!(char_to_ascii('\u{7f}'), "\u{7f}");
        assert_eq!(char_to_ascii('\u{00}'), "\u{00}");
    }

    #[test]
    fn accents() {
        assert_eq!(to_ascii("ñandú café"), "nandu cafe");
    }

    #[test]
    fn unassigned_is_dropped() {
        assert_eq!(to_ascii("a\u{0378}b"), "ab");
    }
}
EOF
echo ok"}

