{"command":"cd /workspace && cat > src/diff.rs <<'EOF'
//! Character level diff between two strings based on the longest common
//! subsequence. It is used to highlight what changed in a file name.

use std::cmp::max;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Difference {
    /// Text present in both strings.
    Same(String),
    /// Text only present in the new string.
    Add(String),
    /// Text only present in the original string.
    Rem(String),
}

/// Compute the differences between `orig` and `edit`, character by character.
///
/// Consecutive differences of the same kind are merged together.
pub fn diff(orig: &str, edit: &str) -> Vec<Difference> {
    let a: Vec<char> = orig.chars().collect();
    let b: Vec<char> = edit.chars().collect();
    let n = a.len();
    let m = b.len();

    // table[i][j] holds the LCS length of a[i..] and b[j..]
    let width = m + 1;
    let mut table = vec![0u32; (n + 1) * (m + 1)];
    for i in (0..n).rev() {
        for j in (0..m).rev() {
            table[i * width + j] = if a[i] == b[j] {
                table[(i + 1) * width + j + 1] + 1
            } else {
                max(table[(i + 1) * width + j], table[i * width + j + 1])
            };
        }
    }

    let mut result: Vec<Difference> = Vec::new();
    let mut push = |item: Difference| match (result.last_mut(), item) {
        (Some(Difference::Same(acc)), Difference::Same(s)) => acc.push_str(&s),
        (Some(Difference::Add(acc)), Difference::Add(s)) => acc.push_str(&s),
        (Some(Difference::Rem(acc)), Difference::Rem(s)) => acc.push_str(&s),
        (_, item) => result.push(item),
    };

    let mut i = 0;
    let mut j = 0;
    while i < n && j < m {
        if a[i] == b[j] {
            push(Difference::Same(a[i].to_string()));
            i += 1;
            j += 1;
        } else if table[(i + 1) * width + j] > table[i * width + j + 1] {
            push(Difference::Rem(a[i].to_string()));
            i += 1;
        } else {
            push(Difference::Add(b[j].to_string()));
            j += 1;
        }
    }
    while i < n {
        push(Difference::Rem(a[i].to_string()));
        i += 1;
    }
    while j < m {
        push(Difference::Add(b[j].to_string()));
        j += 1;
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(orig: &str, edit: &str) -> String {
        diff(orig, edit)
            .into_iter()
            .map(|d| match d {
                Difference::Same(s) => format!("{{={}}}", s),
                Difference::Add(s) => format!("{{+{}}}", s),
                Difference::Rem(_) => String::new(),
            })
            .collect()
    }

    #[test]
    fn simple_cases() {
        assert_eq!(render("abc", "cba"), "{+cb}{=a}");
        assert_eq!(render("file", "elif"), "{+eli}{=f}");
        assert_eq!(render("aaa", "aaaa"), "{=aaa}{+a}");
        assert_eq!(render("abcdef", "xbydzf"), "{+x}{=b}{+y}{=d}{+z}{=f}");
        assert_eq!(render("abcd", "bdac"), "{+bd}{=a}{=c}");
        assert_eq!(render("aXbXc", "abXc"), "{=a}{=bXc}");
        assert_eq!(render("abc", "xyz"), "{+xyz}");
        assert_eq!(render("abcabc", "abc"), "{=abc}");
        assert_eq!(render("", "abc"), "{+abc}");
        assert_eq!(render("abc", ""), "");
    }
}
EOF
echo ok"}

