//! Everything related to printing information to the user: colors, the
//! operation lines (with highlighted changes), errors and info messages.

use std::io::IsTerminal;
use std::path::Path;

use crate::diff::{diff, Difference};
use crate::error::Error;

/// Color mode selected by the user.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorMode {
    Always,
    Never,
    Auto,
}

impl ColorMode {
    /// Decide whether colors must be used for the given mode.
    pub fn enabled(self) -> bool {
        match self {
            ColorMode::Always => true,
            ColorMode::Never => false,
            ColorMode::Auto => std::io::stdout().is_terminal(),
        }
    }
}

/// ANSI SGR sequences used by the printer.
#[derive(Debug, Clone, Copy)]
enum Style {
    Bold,
    Red,
    BoldRed,
    Green,
    Gray,
}

impl Style {
    fn code(self) -> &'static str {
        match self {
            Style::Bold => "1",
            Style::Red => "31",
            Style::BoldRed => "1;31",
            Style::Green => "32",
            Style::Gray => "38;5;8",
        }
    }
}

/// Printer in charge of all the user facing output.
#[derive(Debug, Clone)]
pub struct Printer {
    colors: bool,
    silent: bool,
}

impl Printer {
    /// Create a printer. When `silent` is set nothing is printed and colors
    /// are disabled.
    pub fn new(colors: bool, silent: bool) -> Printer {
        Printer {
            colors: colors && !silent,
            silent,
        }
    }

    pub fn is_silent(&self) -> bool {
        self.silent
    }

    fn paint(&self, style: Style, text: &str) -> String {
        if self.colors {
            format!("\x1b[{}m{}\x1b[0m", style.code(), text)
        } else {
            text.to_string()
        }
    }

    /// Print a line to stdout unless the printer is silent.
    pub fn print(&self, message: &str) {
        if !self.silent {
            println!("{}", message);
        }
    }

    /// Print a line to stderr unless the printer is silent.
    pub fn eprint(&self, message: &str) {
        if !self.silent {
            eprintln!("{}", message);
        }
    }

    /// Format an error as it is shown to the user.
    pub fn format_error(&self, error: &Error) -> String {
        format!(
            "{}{}{}",
            self.paint(Style::Red, "Error: "),
            error.kind.description(),
            self.paint(Style::Red, &error.value)
        )
    }

    /// Print an error to stderr (unless silent).
    pub fn print_error(&self, error: &Error) {
        self.eprint(&self.format_error(error));
    }

    /// Print an error to stderr even if the printer is silent.
    pub fn print_error_forced(&self, error: &Error) {
        eprintln!("{}", self.format_error(error));
    }

    /// Paint the given text in red (used to build error values).
    pub fn red(&self, text: &str) -> String {
        self.paint(Style::Red, text)
    }

    pub fn print_dry_run_header(&self) {
        self.print(&self.paint(Style::Bold, "This is a DRY-RUN"));
    }

    pub fn print_backup_info(&self, source: &Path, backup: &Path) {
        let operation = format!("{} -> {}", source.display(), backup.display());
        self.print(&format!(
            "{} Backup created - {}",
            self.paint(Style::Bold, "Info: "),
            self.paint(Style::Gray, &operation)
        ));
    }

    /// Print a rename operation highlighting the changes in the file name.
    pub fn print_operation(&self, source: &Path, target: &Path) {
        if self.silent {
            return;
        }
        let source_filename = source.file_name().unwrap();
        let source_parent = parent_prefix(source);
        let target_filename = target.file_name().unwrap();
        let target_parent = parent_prefix(target);

        let source_filename = source_filename.to_string_lossy();
        let target_filename = target_filename.to_string_lossy();

        let mut line = String::new();
        if !source_parent.is_empty() {
            line.push_str(&self.paint(Style::Gray, &source_parent));
        }
        line.push_str(&self.paint(Style::Gray, &source_filename));
        line.push_str(" -> ");
        if !target_parent.is_empty() {
            line.push_str(&self.paint(Style::Green, &target_parent));
        }
        for difference in diff(&source_filename, &target_filename) {
            match difference {
                Difference::Same(text) => line.push_str(&self.paint(Style::Green, &text)),
                Difference::Add(text) => line.push_str(&self.paint(Style::BoldRed, &text)),
                Difference::Rem(_) => {}
            }
        }
        self.print(&line);
    }
}

/// Parent directory of a path formatted as a prefix (`dir/`). Empty when the
/// path has no parent directory.
fn parent_prefix(path: &Path) -> String {
    match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => {
            format!("{}/", parent.display())
        }
        _ => String::new(),
    }
}
