//! File system helpers: path collection, backups and renames.

use std::fs;
use std::path::{Path, PathBuf};

use walkdir::{DirEntry, WalkDir};

use crate::cli::PathOptions;
use crate::error::{Error, ErrorKind, Result};

/// Whether a walked entry is hidden (its name starts with a dot). The root
/// entries of a walk are never considered hidden.
fn is_hidden(entry: &DirEntry) -> bool {
    if entry.depth() == 0 {
        return false;
    }
    entry
        .file_name()
        .to_str()
        .map(|name| name.starts_with('.'))
        .unwrap_or(true)
}

/// Collect every path that is a candidate to be renamed.
pub fn collect_paths(options: &PathOptions) -> Vec<PathBuf> {
    let mut collected = Vec::new();

    for path in &options.paths {
        let path = PathBuf::from(path);
        match &options.recursive {
            Some(recursive) => {
                let mut walker = WalkDir::new(&path);
                if let Some(max_depth) = recursive.max_depth {
                    walker = walker.max_depth(max_depth);
                }
                let include_hidden = recursive.hidden;
                let entries = walker
                    .into_iter()
                    .filter_entry(|entry| include_hidden || !is_hidden(entry))
                    .filter_map(|entry| entry.ok());
                for entry in entries {
                    let entry_path = entry.path();
                    if entry_path.is_dir() {
                        if options.include_dirs {
                            collected.push(entry_path.to_path_buf());
                        }
                    } else {
                        collected.push(entry_path.to_path_buf());
                    }
                }
            }
            None => {
                if path.is_dir() {
                    if options.include_dirs {
                        collected.push(path);
                    }
                } else if path.symlink_metadata().is_ok() {
                    collected.push(path);
                }
            }
        }
    }

    collected
}

/// Compute a backup path for a file: `<path>.bk`, or `<path>.bk.N` when the
/// backup already exists.
pub fn backup_path(path: &Path) -> PathBuf {
    let base = format!("{}.bk", path.display());
    let mut candidate = PathBuf::from(&base);
    let mut index = 1u64;
    while candidate.exists() {
        candidate = PathBuf::from(format!("{}.{}", base, index));
        index += 1;
    }
    candidate
}

/// Create a backup copy of a file. Directories are not backed up.
pub fn create_backup(path: &Path) -> Result<Option<PathBuf>> {
    if path.is_dir() {
        return Ok(None);
    }
    let backup = backup_path(path);
    match fs::copy(path, &backup) {
        Ok(_) => Ok(Some(backup)),
        Err(_) => Err(Error::new(
            ErrorKind::CreateBackup,
            path.display().to_string(),
        )),
    }
}

/// Rename a path reporting a descriptive error on failure.
pub fn rename(source: &Path, target: &Path) -> Result<()> {
    fs::rename(source, target).map_err(|err| {
        Error::new(
            ErrorKind::Rename,
            format!("{} -> {}\n{}", source.display(), target.display(), err),
        )
    })
}
