//! Build the rename operations, check for conflicts and sort them so they
//! can be safely applied one after the other.

use std::collections::{BTreeMap, HashMap};
use std::path::{Path, PathBuf};

use crate::error::{Error, ErrorKind, Result};
use crate::output::Printer;

/// A single rename operation.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Operation {
    pub source: PathBuf,
    pub target: PathBuf,
}

/// Map of source path to target path.
pub type RenameMap = HashMap<PathBuf, PathBuf>;

/// Build the rename map applying `rename_fn` to the file name of every path.
/// Paths whose name does not change (or cannot be processed) are ignored.
pub fn build_rename_map<F>(paths: &[PathBuf], rename_fn: F) -> RenameMap
where
    F: Fn(&str) -> String,
{
    let mut rename_map = RenameMap::new();
    for path in paths {
        let file_name = match path.file_name().and_then(|name| name.to_str()) {
            Some(name) => name,
            None => continue,
        };
        let new_name = rename_fn(file_name);
        if new_name == file_name {
            continue;
        }
        let parent = match path.parent() {
            Some(parent) => parent,
            None => continue,
        };
        let target = parent.join(new_name);
        rename_map.entry(path.clone()).or_insert(target);
    }
    rename_map
}

/// Check that two different sources are not renamed to the same target.
fn check_same_target(rename_map: &RenameMap, printer: &Printer) -> Result<()> {
    let sorted: BTreeMap<&PathBuf, &PathBuf> = rename_map.iter().collect();
    let mut seen: HashMap<&Path, &Path> = HashMap::new();
    let mut conflicts = String::new();

    for (source, target) in sorted {
        match seen.get(target.as_path()) {
            Some(first) => {
                conflicts.push_str(&format!(
                    "\n{}->{}\n{}->{}\n",
                    first.display(),
                    target.display(),
                    source.display(),
                    target.display()
                ));
            }
            None => {
                seen.insert(target.as_path(), source.as_path());
            }
        }
    }

    if conflicts.is_empty() {
        Ok(())
    } else {
        Err(Error::new(ErrorKind::SameFilename, printer.red(&conflicts)))
    }
}

/// Check that no target already exists in the file system (unless it is
/// going to be renamed as well).
fn check_existing_targets(rename_map: &RenameMap) -> Result<()> {
    for (source, target) in rename_map {
        if target.exists() && !rename_map.contains_key(target) {
            return Err(Error::new(
                ErrorKind::ExistingPath,
                format!("{} -> {}", source.display(), target.display()),
            ));
        }
    }
    Ok(())
}

/// Order the operations so that a source is never overwritten before being
/// renamed: operations whose target is not another source go first, then the
/// remaining ones are resolved iteratively.
fn resolve_order(rename_map: &RenameMap) -> Result<Vec<Operation>> {
    let mut ordered = Vec::with_capacity(rename_map.len());
    let mut pending: RenameMap = RenameMap::new();

    for (source, target) in rename_map {
        if rename_map.contains_key(target) {
            pending.insert(source.clone(), target.clone());
        } else {
            ordered.push(Operation {
                source: source.clone(),
                target: target.clone(),
            });
        }
    }

    while !pending.is_empty() {
        let before = pending.len();
        for (source, target) in pending.clone() {
            if !pending.contains_key(&target) {
                ordered.push(Operation {
                    source: source.clone(),
                    target,
                });
                pending.remove(&source);
            }
        }
        if pending.len() == before {
            return Err(Error::new(ErrorKind::SolveOrder, ""));
        }
    }

    Ok(ordered)
}

/// Depth of a path (number of components).
fn depth(path: &Path) -> usize {
    path.components().count()
}

/// Validate the rename map and return the operations in a safe order.
/// Deeper paths are renamed first so that directories are renamed after
/// their content.
pub fn solve(rename_map: &RenameMap, printer: &Printer) -> Result<Vec<Operation>> {
    check_same_target(rename_map, printer)?;
    check_existing_targets(rename_map)?;
    let mut operations = resolve_order(rename_map)?;
    operations.sort_by(|a, b| depth(&b.source).cmp(&depth(&a.source)));
    Ok(operations)
}
