//! Application flow: build the operations and apply (or just show) them.

use regex::Captures;

use crate::ascii::to_ascii;
use crate::cli::{Config, Mode, Transform};
use crate::dumpfile;
use crate::error::Result;
use crate::fileutils::{collect_paths, create_backup, rename};
use crate::solver::{build_rename_map, solve, Operation};

/// Apply a transformation to an (already expanded) replacement.
fn apply_transform(transform: Transform, text: &str) -> String {
    match transform {
        Transform::Upper => text.to_uppercase(),
        Transform::Lower => text.to_lowercase(),
        Transform::Ascii => ascii_file_name(text),
    }
}

/// ASCII representation of a file name. Slashes are not allowed in file
/// names, so they are replaced by underscores.
fn ascii_file_name(text: &str) -> String {
    to_ascii(text).replace('/', "_")
}

/// Compute the operations to perform according to the configuration.
fn build_operations(config: &Config) -> Result<Vec<Operation>> {
    match &config.mode {
        Mode::Regex {
            expression,
            replacement,
            limit,
            transform,
            paths,
        } => {
            let collected = collect_paths(paths);
            let rename_map = build_rename_map(&collected, |name| match transform {
                None => expression
                    .replacen(name, *limit, replacement.as_str())
                    .into_owned(),
                Some(transform) => expression
                    .replacen(name, *limit, |captures: &Captures| {
                        let mut expanded = String::new();
                        captures.expand(replacement, &mut expanded);
                        apply_transform(*transform, &expanded)
                    })
                    .into_owned(),
            });
            solve(&rename_map, &config.printer)
        }
        Mode::ToAscii { paths } => {
            let collected = collect_paths(paths);
            let rename_map = build_rename_map(&collected, ascii_file_name);
            solve(&rename_map, &config.printer)
        }
        Mode::FromFile { dump_file, undo } => {
            let mut operations = dumpfile::read(dump_file)?;
            if *undo {
                operations.reverse();
                for operation in &mut operations {
                    std::mem::swap(&mut operation.source, &mut operation.target);
                }
            }
            Ok(operations)
        }
    }
}

/// Run the application with the given configuration.
pub fn run(config: &Config) -> Result<()> {
    let printer = &config.printer;

    if !config.force {
        printer.print_dry_run_header();
    }

    let operations = build_operations(config)?;

    if config.dump {
        dumpfile::write(&operations, &config.dump_prefix)?;
    }

    for operation in &operations {
        if config.force {
            if config.backup {
                if let Some(backup) = create_backup(&operation.source)? {
                    printer.print_backup_info(&operation.source, &backup);
                }
            }
            rename(&operation.source, &operation.target)?;
        }
        printer.print_operation(&operation.source, &operation.target);
    }

    Ok(())
}
