            else:  # prefix table misused in forward walk
                rem_v, add_v = L[i+1][j], L[i][j+1]
            if rem_v > add_v or (rem_v == add_v and not tie_add):
                seq.append(('-', a[i])); i += 1
            else:
                seq.append(('+', b[j])); j += 1
    while i < n: seq.append(('-', a[i])); i += 1
    while j < m: seq.append(('+', b[j])); j += 1
    return seq

def walk_backward(a, b, L, tie_add, which):
    n, m = len(a), len(b); i = n; j = m; seq = []
    while i > 0 and j > 0:
