                }
            } else if i == 0 && j == 0 {
                0
            } else if i == 0 {
                table[j - 1]
            } else if j == 0 {
                table[(i - 1) * m]
            } else {
                max(table[(i - 1) * m + j], table[i * m + (j - 1)])
            };
        }
    }

    let lookup = |i: isize, j: isize| -> usize {
        let flat = i * m as isize + j;
        if flat >= 0 && (flat as usize) < table.len() {
            table[flat as usize]
        } else {
            0
        }
    };

    let mut common = Vec::new();
    let mut i = n as isize - 1;
    let mut j = m as isize - 1;
    while i >= 0 && j >= 0 {
        if a[i as usize] == b[j as usize] {
            common.push(a[i as usize]);
            i -= 1;
            j -= 1;
        } else if lookup(i - 1, j) >= lookup(i, j - 1) {
            i -= 1;
        } else {
            j -= 1;
        }
    }
    common.reverse();
    common
}

/// Align `a` and `b` against their common subsequence, left to right.
fn align(a: &[char], b: &[char], common: &[char]) -> Vec<Difference> {
    let mut result: Vec<Difference> = Vec::new();
    let mut push = |item: Difference| match (result.last_mut(), item) {
        (Some(Difference::Same(acc)), Difference::Same(s)) => acc.push_str(&s),
        (Some(Difference::Add(acc)), Difference::Add(s)) => acc.push_str(&s),
        (Some(Difference::Rem(acc)), Difference::Rem(s)) => acc.push_str(&s),
        (_, item) => result.push(item),
    };

    let mut i = 0;
    let mut j = 0;
    for &c in common {
        while i < a.len() && a[i] != c {
            push(Difference::Rem(a[i].to_string()));
            i += 1;
        }
        while j < b.len() && b[j] != c {
            push(Difference::Add(b[j].to_string()));
            j += 1;
        }
        if i < a.len() && j < b.len() {
            push(Difference::Same(c.to_string()));
            i += 1;
            j += 1;
        }
    }
    while i < a.len() {
        push(Difference::Rem(a[i].to_string()));
        i += 1;
    }
    while j < b.len() {
        push(Difference::Add(b[j].to_string()));
        j += 1;
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    fn render(orig: &str, edit: &str) -> String {
        diff(orig, edit)
            .into_iter()
            .map(|d| match d {
                Difference::Same(s) => format!("{{={}}}", s),
                Difference::Add(s) => format!("{{+{}}}", s),
                Difference::Rem(_) => String::new(),
            })
            .collect()
    }

    #[test]
    fn simple_cases() {
        assert_eq!(render("abc", "cba"), "{+cb}{=a}");
        assert_eq!(render("file", "elif"), "{+eli}{=f}");
        assert_eq!(render("aaa", "aaaa"), "{=aaa}{+a}");
        assert_eq!(render("abcdef", "xbydzf"), "{+x}{=b}{+y}{=d}{+z}{=f}");
        assert_eq!(render("abcd", "bdac"), "{+bd}{=a}{=c}");
        assert_eq!(render("aXbXc", "abXc"), "{=a}{=bXc}");
        assert_eq!(render("abc", "xyz"), "{+xyz}");
        assert_eq!(render("abcabc", "abc"), "{=abc}");
        assert_eq!(render("", "abc"), "{+abc}");
        assert_eq!(render("abc", ""), "");
        assert_eq!(render("ab", "bb"), "{=b}{+b}");
        assert_eq!(render("ab", "ba"), "{+b}{=a}");
        assert_eq!(render("aba", "bba"), "{=b}{+b}{=a}");
        assert_eq!(render("aba", "baa"), "{+b}{=a}{=a}");
    }

    #[test]
    fn reference_quirks() {
        // The common subsequence is not always the longest one.
        assert_eq!(render("abbb", "ab"), "{+a}{=b}");
        assert_eq!(render("aaba", "aa"), "{=a}{+a}");
        assert_eq!(render("xcabcbab", "xba"), "{+x}{=b}{=a}");
    }
}
