            match worker.join() {
                Ok(paths) => paths,
                Err(payload) => std::panic::resume_unwind(payload),
            }
        }
        None => explicit_paths(options),
    }
}

/// Paths given explicitly on the command line (non recursive mode).
fn explicit_paths(options: &PathOptions) -> Vec<PathBuf> {
    let mut collected = Vec::new();
    for path in &options.paths {
        let path = PathBuf::from(path);
        if path.is_dir() {
            if options.include_dirs {
                collected.push(path);
            }
        } else if path.symlink_metadata().is_ok() {
            collected.push(path);
        }
    }
    collected
}

/// Walk the given paths recursively collecting files (and directories when
/// requested).
fn walk_paths(options: &PathOptions) -> Vec<PathBuf> {
    let recursive = options.recursive.as_ref().expect("recursive options");
    let mut collected = Vec::new();
    for path in &options.paths {
        let mut walker = WalkDir::new(path);
        if let Some(max_depth) = recursive.max_depth {
            walker = walker.max_depth(max_depth);
        }
        let include_hidden = recursive.hidden;
        let entries = walker
            .into_iter()
            .filter_entry(|entry| include_hidden || !is_hidden(entry))
            .filter_map(|entry| entry.ok());
        for entry in entries {
            let entry_name: &str = entry.file_name().to_str().unwrap();
            debug_assert!(!entry_name.is_empty());
            let entry_path = entry.path();
            if entry_path.is_dir() {
